import zipfile
import re
import xml.etree.ElementTree as ET

NS = {
    'm': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
    'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
    'pr': 'http://schemas.openxmlformats.org/package/2006/relationships',
}

def q(tag):
    return '{http://schemas.openxmlformats.org/spreadsheetml/2006/main}' + tag

def qr(tag):
    return '{http://schemas.openxmlformats.org/officeDocument/2006/relationships}' + tag

def qp(tag):
    return '{http://schemas.openxmlformats.org/package/2006/relationships}' + tag

with zipfile.ZipFile('budget.xlsx') as z:
    names = z.namelist()
    print("ZIP entries:")
    for n in names:
        print(" ", n)

    # workbook.xml -> sheet name + r:id
    wb_root = ET.fromstring(z.read('xl/workbook.xml'))
    sheets = []
    for sh in wb_root.find(q('sheets')):
        sheets.append((sh.get('name'), sh.get(qr('id'))))
    print("Sheets (name, r:id):", sheets)

    # workbook.xml.rels -> r:id -> target
    rels_root = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    rel_map = {}
    for rel in rels_root:
        rel_map[rel.get('Id')] = rel.get('Target')
    print("Rels:", rel_map)

    # shared strings
    shared = []
    if 'xl/sharedStrings.xml' in names:
        ss_root = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in ss_root.findall(q('si')):
            text = ''.join(t.text or '' for t in si.iter(q('t')))
            shared.append(text)
    print("Shared strings count:", len(shared))

    for sheet_name, rid in sheets:
        target = rel_map.get(rid)
        path = 'xl/' + target if not target.startswith('/') else target.lstrip('/')
        print(f"\n=== Sheet: {sheet_name} ({path}) ===")
        root = ET.fromstring(z.read(path))
        sheet_data = root.find(q('sheetData'))
        for row in sheet_data.findall(q('row')):
            r = row.get('r')
            cells = []
            for c in row.findall(q('c')):
                ref = c.get('r')
                t = c.get('t')
                v = c.find(q('v'))
                f = c.find(q('f'))
                val = None
                if f is not None:
                    val = '=' + (f.text or '')
                elif v is not None and v.text is not None:
                    if t == 's':
                        val = shared[int(v.text)]
                    elif t == 'str' or t == 'inlineStr':
                        val = v.text
                    else:
                        val = v.text
                elif t == 'inlineStr':
                    is_el = c.find(q('is'))
                    if is_el is not None:
                        val = ''.join(x.text or '' for x in is_el.iter(q('t')))
                cells.append(f"{ref}={val!r}" if val is not None else ref)
            if cells:
                print(f"row {r}: " + " | ".join(cells))

